head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_digital.js");
// 상장관련공통함수
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

//화면ID
scwin.vScrenID = "ULDSTF70030.xml";
scwin.pNmChgID = "ULDSTF70030_N"; // 종목명변경/증권분할병합 신규(수정) 팝업 화면
scwin.pQtyChgID = "ULDSTF70030_N2"; //  기타 수량감소 -신규(수정) 팝업화면
scwin.pExpChgID = "ULDSTF70030_N3"; // 만기변경 신규(수정) 팝업화면
scwin.pEtcChgID = "ULDSTF70030_N4"; // 기타변경 신규(수정) 팝업화면

//팝업에서 사용될 변수
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.clickBzProcsNo = ""; // 업무처리번호
scwin.clickIsuCd = ""; // 종목코드
scwin.clickIsuNm = ""; // 종목명
scwin.clickBzTpCd = ""; // 상장유형코드
scwin.clickIsurCd = ""; // 상장인신청인코드
scwin.clickIsurNm = ""; // 상장신청인명
scwin.clickDisclsYn = ""; // 공시여부

//그리드 조회된 결과없습니다. 메세지 show/hide 용 위한 변수
scwin.vTotalCountGrid1 = 0;
scwin.vIsuChgKind = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // 팝업 구분 (신규:N, 수정:U) > 팝업 전달인자

/********************************************** 
 * 함수명 : fn_list_nm_chglist_sync()
 * 설명    : 종목명변경의 종목명 변경상장 내역 조회
 ***********************************************/
scwin.fn_list_nm_chglist_sync = function() {
    //발행 및 상장 내역 조회
    var url = "/digital/DigitalListinvstg.do?method=listDigitalNameChangeRequest";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&SRCH_COM_CD=" + $c.stf.getObjectValue(txb_ISUR_CD1); // 상장신청인
    url += "&SRCH_ISU_CD=" + $c.stf.getObjectValue(txb_SearchIsuCd1); // 종목코드


    dts_nm_change.DataID = encodeURI(url);
    dts_nm_change.Reset();

    //'조회된결과없습니다' 메세지숨김 
    if (scwin.vTotalCountGrid1 > 0) {
        $c.lcd.fn_CloseNoData();
    } else {
        $c.cm.ShowNoData(grd_Itm_List1);
    }
};



/********************************************** 
 * 함수명 : fn_list_qty_chglist_sync()
 * 설명    : 기타수량감소 내역 조회
 ***********************************************/
scwin.fn_list_qty_chglist_sync = function() {
    //발행 및 상장 내역 조회
    var url = "/digital/DigitalListinvstg.do?method=listDigitalQtyChangeRequest";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&SRCH_COM_CD=" + $c.stf.getObjectValue(txb_ISUR_CD1);
    url += "&SRCH_ISU_CD=" + $c.stf.getObjectValue(txb_SearchIsuCd1);
    dts_qty_change.DataID = encodeURI(url);
    dts_qty_change.Reset();


    //'조회된결과없습니다' 메세지숨김 (그리드 2개중 하나라도 데이터 0개 이면)
    if (scwin.vTotalCountGrid1 > 0) {
        $c.lcd.fn_CloseNoData();
    } else {
        $c.cm.ShowNoData(grd_Itm_List2);
    }
};





/********************************************** 
 * 함수명 : fn_list_exp_chglist_sync()
 * 설명    : 만기변경 내역 조회
 ***********************************************/
scwin.fn_list_exp_chglist_sync = function() {
    //발행 및 상장 내역 조회
    var url = "/digital/DigitalListinvstg.do?method=listDigitalExpChangeRequest";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&SRCH_COM_CD=" + $c.stf.getObjectValue(txb_ISUR_CD1);
    url += "&SRCH_ISU_CD=" + $c.stf.getObjectValue(txb_SearchIsuCd1);
    dts_exp_change.DataID = encodeURI(url);
    dts_exp_change.Reset();


    //'조회된결과없습니다' 메세지숨김 (그리드 2개중 하나라도 데이터 0개 이면)
    if (scwin.vTotalCountGrid1 > 0) {
        $c.lcd.fn_CloseNoData();
    } else {
        $c.cm.ShowNoData(grd_Itm_List3);
    }
};




/********************************************** 
 * 함수명 : fn_list_etc_chglist_sync()
 * 설명    : 기타변경 내역 조회
 ***********************************************/
scwin.fn_list_etc_chglist_sync = function() {
    //발행 및 상장 내역 조회
    var url = "/digital/DigitalListinvstg.do?method=listDigitalEtcChangeRequest";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&SRCH_COM_CD=" + $c.stf.getObjectValue(txb_ISUR_CD1);
    url += "&SRCH_ISU_CD=" + $c.stf.getObjectValue(txb_SearchIsuCd1);
    dts_etc_change.DataID = encodeURI(url);
    dts_etc_change.Reset();


    //'조회된결과없습니다' 메세지숨김 (그리드 2개중 하나라도 데이터 0개 이면)
    if (scwin.vTotalCountGrid1 > 0) {
        $c.lcd.fn_CloseNoData();
    } else {
        $c.cm.ShowNoData(grd_Itm_List4);
    }
};



/********************************************** 
 * 함수명 : fn_GetParIsur(), fn_SetParIsur()
 * 설명    : 상장신청인 호출관련
 ***********************************************/
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_ISUR_CD1); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_ISUR_NM1); // 명칭값을 포함할 컨트롤
    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISUR_CD1.setValue(arrPar[0].ISUR_CD);
        txb_ISUR_NM1.setValue(arrPar[0].ISUR_NM);
    }
};



/********************************************** 
 * 함수명 : fn_GetParIsur2(), fn_SetParIsur2()
 * 설명    : 종목명 호출관련
 ***********************************************/
scwin.fn_GetParIsur2 = function(arrPar) {
    // 넘길 인수를 지정하는 펑션

    arrPar[0] = $c.stf.getObjectValue(txb_SearchIsuCd1); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_SearchIsuNm1); // 명칭값을 포함할 컨트롤

    return arrPar.length;
};
scwin.fn_SetParIsur2 = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    scwin.fn_setCodeIsur(arrPar[0].ISUR_CD); // 상장신청인 정보 불러오기

    if (dbClickYn == "Y") {
        txb_SearchIsuCd1.setValue(arrPar[0].ISU_CD);
        txb_SearchIsuNm1.setValue(arrPar[0].ISU_KOR_ABBRV);
    }
};
scwin.fn_setCodeIsur = function(sIsuCd) {
    //상장신청인 정보 조회하기
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=DIGITAL_ADMISU_ISU_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.digital.select.isurcdalL_p2.condition" + "&{P}param01=" + sIsuCd;
    dts_IsuCd.DataID = encodeURI(url);
    dts_IsuCd.reset();
};




/********************************************** 
 * 함수명 : fn_PopIsuNmChg(kind)
 * Param  : kind (N:신규, U:수정)
 * 설명    : 종목명변경  > 종목명변경 상장내역 > 팝업
 ***********************************************/
scwin.fn_PopIsuNmChg = async function(kind, rowno, colid) {
    vPTitle = "종목명변경/증권분할·병합 ";
    scwin.vIsuChgKind = kind; // 팝업전달인자(N:신규, U:수정)

    if (kind == "N") {
        //row data of grid
        scwin.clickBzProcsNo = "";
        scwin.clickIsuCd = $c.stf.getObjectValue(txb_SearchIsuCd1);
        vPTitle = vPTitle + "신규";
    } else if (kind == "U") {
        //data of textcontrol
        scwin.clickBzProcsNo = dts_nm_change.getCellData(rowno, "BZ_PROCS_NO"); // 업무처리코드
        scwin.clickIsuCd = dts_nm_change.getCellData(rowno, "ISU_CD"); // 종목명코드
        scwin.clickDisclsYn = dts_nm_change.getCellData(rowno, "DISCLS_YN"); // 공시여부

        vPTitle = vPTitle + "세부내역";
    }
    await $c.frame.CreateDialogFrame(scwin.pNmChgID, "../digital/" + scwin.pNmChgID + ".gfm", vPTitle, 20, 00, 850, 510, "window");
};



/********************************************** 
 * 함수명 : fn_PopQtyIsur(kind)
 * Param  : kind (N:신규, U:수정)
 * 설명    : 변경상장  > 기타수량감소  > 팝업
 ***********************************************/
scwin.fn_PopQtyIsur = async function(kind, rowno, colid) {
    vPTitle = "기타수량감소 ";
    scwin.vIsuChgKind = kind; // 팝업전달인자(N:신규, U:수정)

    if (kind == "N") {
        scwin.clickBzTpCd = ""; // 상장유형코드
        scwin.clickIsuCd = $c.stf.getObjectValue(txb_SearchIsuCd1); // 종목코드
        scwin.clickIsurCd = $c.stf.getObjectValue(txb_ISUR_CD1); // 상장신청인코드
        scwin.clickIsurNm = $c.stf.getObjectValue(txb_ISUR_NM1); // 상장신청인명

        vPTitle = vPTitle + " 신규";
    } else if (kind == "U") {
        scwin.clickBzProcsNo = dts_qty_change.getCellData(rowno, "BZ_PROCS_NO"); // 업무처리번호
        scwin.clickDisclsYn = dts_qty_change.getCellData(rowno, "DISCLS_YN"); // 공시여부 
        scwin.clickIsuCd = dts_qty_change.getCellData(rowno, "ISU_CD"); // 종목코드
        scwin.clickBzTpCd = dts_qty_change.getCellData(rowno, "LIST_BZ_TP_CD"); // 상장유형코드

        vPTitle = vPTitle + " 세부내역";
    }
    await $c.frame.CreateDialogFrame(scwin.pQtyChgID, "../digital/" + scwin.pQtyChgID + ".gfm", vPTitle, 20, 00, 790, 420, "window");
};




/********************************************** 
 * 함수명 : fn_PopExpIsur(kind)
 * Param  : kind (N:신규, U:수정)
 * 설명    : 변경상장 > 만기변경  > 팝업
 ***********************************************/
scwin.fn_PopExpIsur = async function(kind, rowno, colid) {
    vPTitle = "만기변경 ";
    scwin.vIsuChgKind = kind; // 팝업전달인자(N:신규, U:수정)

    if (kind == "N") {
        scwin.clickIsuCd = $c.stf.getObjectValue(txb_SearchIsuCd1); // 종목코드
        vPTitle = vPTitle + " 신규";
    } else if (kind == "U") {
        scwin.clickBzProcsNo = dts_exp_change.getCellData(rowno, "BZ_PROCS_NO"); // 업무처리번호 
        scwin.clickIsuCd = dts_exp_change.getCellData(rowno, "ISU_CD"); // 종목코드
        scwin.clickDisclsYn = dts_exp_change.getCellData(rowno, "DISCLS_YN"); // 공시여부 

        vPTitle = vPTitle + " 세부내역";
    }
    await $c.frame.CreateDialogFrame(scwin.pExpChgID, "../digital/" + scwin.pExpChgID + ".gfm", vPTitle, 20, 00, 750, 400, "window");
};




/********************************************** 
 * 함수명 : fn_PopEtcIsur(kind)
 * Param  : kind (N:신규, U:수정)
 * 설명    : 변경상장 > r기타변경  > 팝업
 ***********************************************/
scwin.fn_PopEtcIsur = async function(kind, rowno, colid) {
    scwin.vIsuChgKind = kind; // 팝업전달인자(N:신규, U:수정)

    vPTitle = "기타변경 ";
    if (kind == "N") {
        scwin.clickIsuCd = $c.stf.getObjectValue(txb_SearchIsuCd1); // 종목코드
        scwin.clickIsuNm = $c.stf.getObjectValue(txb_SearchIsuNm1); // 종목명
        vPTitle = vPTitle + " 신규";
    } else if (kind == "U") {
        scwin.clickBzProcsNo = dts_etc_change.getCellData(rowno, "BZ_PROCS_NO"); // 업무처리번호
        scwin.clickIsuCd = dts_etc_change.getCellData(rowno, "ISU_CD"); // 종목코드
        scwin.clickDisclsYn = dts_etc_change.getCellData(rowno, "DISCLS_YN"); // 공시여부 
        vPTitle = vPTitle + " 세부내역";
    }
    await $c.frame.CreateDialogFrame(scwin.pEtcChgID, "../digital/" + scwin.pEtcChgID + ".gfm", vPTitle, 20, 00, 870, 510, "window");
};

/********************************************** 
 * 함수명 : fn_read_sync(msgKind)
 * Param  : msgKind (Y:메시지출력, N:메시지미출력)
 * 설명    : 변경상장 > 조회
 ***********************************************/
scwin.fn_read_sync = function(msgKind) {
    //필수값 체크 	
    // 상장인 명 또는 종목  선택 조회가능
    if ($c.ut.trim($c.stf.getObjectValue(txb_ISUR_CD1)) == "" & $c.ut.trim($c.stf.getObjectValue(txb_SearchIsuCd1)) == "") {
        if (msgKind == 'Y') {
            $c.win.alert("상장신청인 또는 종목을 선택해주세요.");
        }
        return;
    }
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        dts_nm_change.removeAll();
        //종목명 변경 조회
        scwin.fn_list_nm_chglist_sync();
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        dts_qty_change.removeAll();
        // 기타수량감소 조회
        scwin.fn_list_qty_chglist_sync();
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        dts_exp_change.removeAll();
        // 만기변경 조회
        scwin.fn_list_exp_chglist_sync();
    } else {
        dts_etc_change.removeAll();
        // 기타 변경 조회			
        scwin.fn_list_etc_chglist_sync();
    }
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", procJob));
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001", procJob));
};
scwin.gform_onload = function() {
    MaxTab_01.setSelectedTabIndex("1");
};
scwin.btn_New_onclick = function() {
    // 신규 팝업 버튼 클릭
    if ($c.stf.getObjectValue(txb_SearchIsuCd1) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        return;
    }
    if (MaxTab_01.getSelectedTabIndex() == "1") {
        // 종목명 변경 또는 증권의 분할/병합
        scwin.fn_PopIsuNmChg("N", -1, ""); //-1은 의미 없음

    } else if (MaxTab_01.getSelectedTabIndex() == "2") {
        // 기타감소
        scwin.fn_PopQtyIsur("N", -1, ""); //-1은 의미 없음			

    } else if (MaxTab_01.getSelectedTabIndex() == "3") {
        //만기변경
        scwin.fn_PopExpIsur("N", -1, ""); //-1은 의미 없음

    } else {
        //기타변경
        scwin.fn_PopEtcIsur("N", -1, ""); //-1은 의미 없음

    }
};
scwin.btn_Close_onclick = async function() {
    // 닫기
    await $c.frame.CloseFrame();
};
scwin.btn_Excel_onclick = function() {
    // 엑셀저장
    var isExcelDown = false;
    var xls_path;
    var countIsur = 0;
    var today = $c.ut.cGetToday("yyyymmddhhmmss");
    if (MaxTab_01.getSelectedTabIndex() == "1") {
        countIsur = dts_nm_change.getTotalRow();
        if (countIsur > 0) {
            $c.data.downloadGridViewExcel(grd_Itm_List1, "종목명/증권분할·병합 내역", "", 8);
        } else {
            $c.win.alert("[엑셀]로 저장하려는 데이터가 없습니다.");
        }
    } else if (MaxTab_01.getSelectedTabIndex() == "2") {
        countIsur = dts_qty_change.getTotalRow();
        if (countIsur > 0) {
            $c.data.downloadGridViewExcel(grd_Itm_List2, "기타수량감소 내역", "", 8);
        } else {
            $c.win.alert("[엑셀]로 저장하려는 데이터가 없습니다.");
        }
    } else if (MaxTab_01.getSelectedTabIndex() == "3") {
        countIsur = dts_exp_change.getTotalRow();
        if (countIsur > 0) {
            $c.data.downloadGridViewExcel(grd_Itm_List3, "만기변경 내역", "", 8);
        } else {
            $c.win.alert("[엑셀]로 저장하려는 데이터가 없습니다.");
        }
    } else {
        countIsur = dts_etc_change.getTotalRow();
        if (countIsur > 0) {
            $c.data.downloadGridViewExcel(grd_Itm_List4, "기타변경 내역", "", 8);
        } else {
            $c.win.alert("[엑셀]로 저장하려는 데이터가 없습니다.");
        }
    }
};
scwin.grd_Itm_List1_OnDblClick = function(row, colid) {
    //변경상장>종목명변경/증권분할병합>데이터 Row Click
    scwin.fn_PopIsuNmChg("U", row, colid);
};
scwin.grd_Itm_List2_OnDblClick = function(row, colid) {
    //변경상장>기타수량감소> 데이터 Row Click
    scwin.fn_PopQtyIsur("U", row, colid);
};
scwin.grd_Itm_List3_OnDblClick = function(row, colid) {
    //변경상장>만기변경> 데이터 Row Click
    scwin.fn_PopExpIsur("U", row, colid);
};
scwin.grd_Itm_List4_OnDblClick = function(row, colid) {
